cgal_domain::cgal_domain(){
}

cgal_domain::~cgal_domain(){

}

// Initialize domain
void cgal_domain::initialize(){
	num_subdomains = 0;
	clearSubDomains();
	clearDomainFeatures();
	setImageDefaultParameters();
}

// Set domain outer box: length and minimum discretization in
// each direction
void cgal_domain::setDomainBox(const double x0, const double y0, const double z0,
		const double xl, const double yl, const double zl,
		const double dx, const double dy, const double dz){
	xcoord = x0;
	ycoord = y0;
	zcoord = z0;

	xlen = xl;
	ylen = yl;
	zlen = zl;

	xdim = ceil(xl/dx);
	ydim = ceil(yl/dy);
	zdim = ceil(zl/dz);

	dxmin = xl/xdim;
	dymin = yl/ydim;
	dzmin = zl/zdim;

	//allocate space for data storage
	int n = xdim*ydim*zdim;
	data = (char*)malloc(sizeof(char)*n);

	for(int i=0; i<n; i++){
		data[i] = 0;
	}

	//set dimension value
	if (xdim > 1 && ydim > 1 && zdim > 1){
		ndim = 3;
	}
	else if ((xdim > 1 && ydim > 1) ||
			 (xdim > 1 && zdim > 1) ||
			 (ydim > 1 && zdim > 1)){
		ndim = 2;
	}
	else if (xdim > 1 || ydim > 1 || zdim > 1){
		ndim = 1;
	}
	else{
		ndim =  0;
	}
}

// Set mesh criteria
void cgal_domain::setDomainCriteria(const double edgeSize,
		const double facetAngle, const double facetSize,
		const double facetDistance, const double cellRadiusEdgeRatio,
		const double globalSize){
	criteriaEdgeSize = edgeSize;
	criteriaFacetAngle = facetAngle;
	criteriaFacetSize = facetSize;
	criteriaFacetDistance = facetDistance;
	criteriaCellRadiusEdgeRatio = cellRadiusEdgeRatio;
	critieriaGlobalSize = globalSize;
}

// Output the domain information to inr image file
/* An example of an image file:
#INRIMAGE-4#{
XDIM=128   // x dimension
YDIM=128   // y dimension
ZDIM=128   // z dimension
VDIM=1      // number of scalar per voxel (1 = scalar image, 3 = 3D image of vectors)
VX=0.66   // voxel size in x
VY=0.66   // voxel size in y
VZ=1       // voxel size in z
TYPE=unsigned fixed   // float, signed fixed, or unsigned fixed
PIXSIZE=16 bits   // 8, 16, 32, or 64
SCALE=2**0       // not used in my program
CPU=decm           // decm, alpha, pc, sun, sgi
                          // little endianness : decm, alpha, pc; big endianness :sun, sgi

    // fill with carriage return or with any other information

##} // until the total size of the header is 256 characters (including final newline character)
// raw data, size=XDIM*YDIM*ZDIM*VDIM*PIXSIZE/8 */
void cgal_domain::makeOutputImage(const std::string strfile){
	std::string header = "#INRIMAGE-4#{\n";
	header.append("XDIM=");
	header.append(std::to_string(xdim));
	header.append("\n");
	header.append("YDIM=");
	header.append(std::to_string(ydim));
	header.append("\n");
	header.append("ZDIM=");
	header.append(std::to_string(zdim));
	header.append("\n");
	header.append("VDIM=");
	header.append(std::to_string(vdim));
	header.append("\n");
	header.append("TYPE=");
	header.append(datatype);
	header.append("\n");
	header.append("PIXSIZE=");
	header.append(pixsize);
	header.append("\n");
	header.append("CPU=");
	header.append(cpu);
	header.append("\n");
	header.append("VX=");
	header.append(std::to_string(dxmin));
	header.append("\n");
	header.append("VY=");
	header.append(std::to_string(dymin));
	header.append("\n");
	header.append("VZ=");
	header.append(std::to_string(dzmin));
	header.append("\n");
	std::string headerEND = "##}\n";

	// INR file
	std::ofstream fp(strfile, std::ios::out | std::ios::binary);

	// output .inr header
	int hlen = 256 - header.length() - headerEND.length();
	for (int i=0; i<hlen; i++){
		header += '\n';
	}

	header += headerEND;

	fp.write(header.c_str(), header.size());

	// output label data to .inr
	fp.write(data, xdim*ydim*zdim );
	fp.close();

	// clean-up
	free(data);
}

// Optimization parameters of Lloyd
void cgal_domain::setOptParametersLloyd(const int maxIteration,
		const double timeLimit){
	maxIterationLloyd = maxIteration;
	timeLimitLloyd = timeLimit;
	b_opt_lloyd = true;
}

// Optimization parameters of Exude
void cgal_domain::setOptParametersExude(const double sliverBound,
		const double timeLimit){
	sliverBoundExude = sliverBound;
	timeLimitExude = timeLimit;
	b_opt_exude = true;
}

// Optimization parameters of Perturb
void cgal_domain::setOptParametersPerturb(const double silverBound,
		const double timeLimit){
	sliverBoundPerturb = silverBound;
	timeLimitPerturb = timeLimit;
	b_opt_perturb = true;
}

// generate and output mesh file based on the inr image file
void cgal_domain::makeOutputMesh(const std::string strImageFile,
		const std::string strMeshFile, const std::string strMeshFormat){
	// Loads image
	CGAL::Image_3 image;
	image.read(strImageFile.c_str());
	// Domain
	Mesh_domain domain(image);

	int volume_dimension = ndim;
	Sizing_field size(critieriaGlobalSize);

	std::list<cgal_subdomain>::iterator subdomainIterator;
	for (subdomainIterator=subdomains.begin();
			subdomainIterator!=subdomains.end();++subdomainIterator){
		double size_subdomain = subdomainIterator->DomainSize();
		char label = subdomainIterator->DomainLabel();
		// Sizing field: set global size to 1 and other size based on the label value
		size.set_size(size_subdomain, volume_dimension,
				domain.index_from_subdomain_index(label));
	}

	// Mesh criteria
	Mesh_criteria criteria(edge_size = criteriaEdgeSize,
			facet_angle=criteriaFacetAngle,
			facet_size=criteriaFacetSize,
			facet_distance=criteriaFacetDistance,
			cell_radius_edge_ratio=criteriaCellRadiusEdgeRatio,
			cell_size=size);

	// Add 1d polyline features
	domain.add_features(domain_features.begin(), domain_features.end());

	// Meshing
	C3t3 c3t3 = CGAL::make_mesh_3<C3t3>(domain, criteria, no_perturb(), no_exude());


	// Optional, Optimize 3d mesh using lloyd_optimize_mesh_3 method
	if(b_opt_lloyd){
	  CGAL::lloyd_optimize_mesh_3(c3t3, domain,
			max_iteration_number = maxIterationLloyd, time_limit=timeLimitLloyd);
	}

	// Optimize 3d mesh using exude_mesh_3 method
	if(b_opt_exude){
	  CGAL::exude_mesh_3(c3t3, sliver_bound=sliverBoundExude,time_limit=timeLimitExude);
	}

	// Optimize 3d mesh using perturb_mesh_3 method
	if(b_opt_perturb){
	  CGAL::perturb_mesh_3(c3t3, domain, sliver_bound=sliverBoundPerturb,
			time_limit=timeLimitPerturb);
	}

	// Get mesh information
	const Tr& tr = c3t3.triangulation();
    // number of vertices
	mesh_vertices_counter = 0;
    for(Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
    		vit!=tr.finite_vertices_end();vit++){
    	mesh_vertices_counter = mesh_vertices_counter + 1;
    }

	//Number of edges
	mesh_edges_counter = 0;
    for(Tr::Finite_edges_iterator eit=tr.finite_edges_begin();
    		eit!=tr.finite_edges_end();eit++){
		mesh_edges_counter = mesh_edges_counter + 1;
	}

	//Number of faces
	mesh_faces_counter = 0;
    for(Tr::Finite_facets_iterator fit=tr.finite_facets_begin();
    		fit!=tr.finite_facets_end();fit++){
    	mesh_faces_counter = mesh_faces_counter + 1;
	}

	//Number of surface faces
	mesh_surface_faces_counter = 0;
	for (C3t3::Facets_in_complex_iterator
				fit = c3t3.facets_in_complex_begin();
				fit != c3t3.facets_in_complex_end();fit++){
		mesh_surface_faces_counter = mesh_surface_faces_counter + 1;
	}

	//Number of cells
	mesh_cells_counter = 0;
	for (C3t3::Cells_in_complex_iterator
			cit = c3t3.cells_in_complex_begin();
			cit != c3t3.cells_in_complex_end();cit++){
		mesh_cells_counter = mesh_cells_counter + 1;
	}

	// Output
	if (strMeshFormat == "mesh"){
		std::ofstream medit_file(strMeshFile.c_str());
		c3t3.output_to_medit(medit_file);
	}
	else {
		// Vertices list with index
		std::map<Point3d, int> map_vts;

		//Note: index in off file is 0-based and msh file format is 1-based
		int ivertex = 0;
		int ishift = 0;
		int ncells = 0;

		// Open file
		std::ofstream out;
		out.open(strMeshFile.c_str());

        // Create vertex index
		for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
				vit!=tr.finite_vertices_end();vit++){
			Point3d pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;
		}

		if (strMeshFormat == "off"){

			// Note: index in off file format is 0-based
			ishift = 0;

			// Write header
			out << "OFF" << endl;

			//Off file head information
			out << mesh_vertices_counter << " "
				<< mesh_cells_counter << " 0 " << endl;

	        // Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			// Write cells
			for (C3t3::Cells_in_complex_iterator
					cit = c3t3.cells_in_complex_begin();
					cit != c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				out << "4 " << map_vts[pt0]+ishift << " " << map_vts[pt1]+ishift
					<< " " << map_vts[pt2]+ishift << " " << map_vts[pt3]+ishift << " " << endl;
			}
		}
		else if (strMeshFormat == "msh"){
			// Note: index in msh file format is 1-based
			ishift = 1;

			// Write header
			out << "$MeshFormat" << endl;
			out << "2.2 0 8" << endl;
			out << "$EndMeshFormat" << endl;
			// Write nodes/vertices
			out << "$Nodes" << endl;
			out << mesh_vertices_counter << endl;
			// Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << map_vts[pt] + ishift << " " << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			out << "$EndNodes" << endl;

			// Write elements/cells
			out << "$Elements" << endl;
			out << mesh_cells_counter << endl;
			for (C3t3::Cells_in_complex_iterator
					cit = c3t3.cells_in_complex_begin();
					cit != c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				ncells = ncells + 1;
				//Write 4-node triangles, number of tags are set to 2 with tag value 0, hardwired
				out << ncells << " 4 2 0 0 " << map_vts[pt0]+ishift << " "
					<< map_vts[pt1]+ishift << " " << map_vts[pt2]+ishift
					<< " " << map_vts[pt3]+ishift << " " << endl;
			}
			out << "$EndElements" << endl;
		}
		else if (strMeshFormat == "vtk"){
			//Note: index in vtk file format is 0-based
			// Output the mesh to file

			// Write header
			out << "# vtk DataFile Version 2.0" << endl;
			out << "CGAL mesh generation 3d" << endl;
			out << "ASCII" << endl;
			out << "DATASET UNSTRUCTURED_GRID" << endl;

			// Write nodes/vertices
			out << "POINTS " << mesh_vertices_counter << " double" << endl;

			// Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			out << endl;

			// Write elements/cells
			out << "CELLS " << mesh_cells_counter << " " << mesh_cells_counter*5 << endl;

			for (C3t3::Cells_in_complex_iterator
					cit = c3t3.cells_in_complex_begin();
					cit != c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				//Write 4-node triangles, number of tags are set to 2 with tag value 0, hardwired
				out << "4 " << map_vts[pt0] << " " << map_vts[pt1] << " "
						<< map_vts[pt2]	<< " " << map_vts[pt3] << " " << endl;
			}
			out << endl;

			// Write cell type
			out << "CELL_TYPES " << mesh_cells_counter << endl;

		    for (int icell = 0; icell < mesh_cells_counter; icell++){
		   	  out << "10" << endl;
		    }
			out << endl;
		}
        // Close file
        out.close();
	}

}

// Add subdomain by off file
int cgal_domain::addSubDomain(const int id, const std::string name, const double size,
		const std::string strDomainOffFile){
	cgal_subdomain subdomain(id,name,size);
	std::string strDomainOffTriFile = strDomainOffFile;
	strDomainOffTriFile.append(".tri");
	int iflag = subdomain.makeSurfaceMeshToOff(strDomainOffFile,strDomainOffTriFile);
	if (iflag == 1){
		iflag = subdomain.makePolyhedron(strDomainOffTriFile);
		if (iflag == 1){
			num_subdomains++;
			char label = num_subdomains;
			subdomain.setDomainLabel(label);
			subdomains.push_back(subdomain);
			return 1;
		}
	}
	return 0;
}

// Add polyline feature
void cgal_domain::addFeaturePolyline(const Polyline polyline){
	domain_features.push_back(polyline);
}

// Clear subdomains
void cgal_domain::clearSubDomains(){
	subdomains.clear();
}

// Clear domain features
void cgal_domain::clearDomainFeatures(){
	domain_features.clear();
}

// get number of subdomains
int cgal_domain::numSubDomains(){
	return num_subdomains;
}

// Get subdomain by domain id
cgal_subdomain cgal_domain::getSubDomain(const int id){
	std::list<cgal_subdomain>::iterator subdomainIterator;
	for (subdomainIterator=subdomains.begin();
			subdomainIterator!=subdomains.end();++subdomainIterator){
		if (subdomainIterator->DomainID() == id){
			return *subdomainIterator;
		}
	}
}

// Set domain data value according the subdomain information
void cgal_domain::setDomainDataValue(){
	std::list<cgal_subdomain>::iterator subdomainIterator;
	for (subdomainIterator=subdomains.begin();
			subdomainIterator!=subdomains.end();++subdomainIterator){

		Polyhedron poly = subdomainIterator->polyHedron();
		char label = subdomainIterator->DomainLabel();

		CGAL::Side_of_triangle_mesh<Polyhedron, K> inside(poly);

		for (int iz=0; iz<zdim; iz++){
			for (int iy=0; iy<ydim; iy++){
				for (int ix=0; ix<xdim; ix++){
					int idx = iz*xdim*ydim + iy*xdim + ix;
					double x = ix*dxmin + xcoord;
					double y = iy*dymin + ycoord;
					double z = iz*dzmin + zcoord;
					Point3d pt(x,y,z);
					CGAL::Bounded_side res = inside(pt);
				    if (res == CGAL::ON_BOUNDED_SIDE){
				    	data[idx] = label;
				    }
				}
			}
		}
	}
}

// Set default image parameters
void cgal_domain::setImageDefaultParameters(){
	// number of scalar per voxel (1 = scalar image, 3 = 3D image of vectors)
	vdim = 1;
	//data type float, signed fixed, or unsigned fixed
	datatype = "unsigned fixed";
	//data pixsize, 8, 16, 32, or 64
	pixsize  = "8 bits";
	//scale value, not used in this program
	datascale = "2**0";
	//CPU type, decm, alpha, pc, sun, sgi,
	//little endianness : decm, alpha, pc; big endianness :sun, sgi
	cpu = "decm";
}

// Set optimization default parameters
void cgal_domain::setMeshingDefaultParameters(){
	b_opt_lloyd = false;
	b_opt_exude = false;
	b_opt_perturb = false;
}

